steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      {
        issue(identifier: \"WEB-5\") {
          id
          identifier
          title
          comments(first: 50) {
            nodes {
              id
              body
              resolved
              createdAt
              updatedAt
              user {
                id
                name
              }
            }
          }
        }
      }
    "
  }'
